mapper.select:
SELECT T.orderId, T.orderItemId, T.productId, T.confirmedAt, T.itemSalesAmount, T.deliveryFeeAmount, T.returnFeeAmount, T.returnFeePayer, T.feeRate, T.itemType, T.orderNo, T.productName FROM ( SELECT oi.ORDER_ID AS orderId, oi.ORDER_ITEM_ID AS orderItemId, oi.PRODUCT_ID AS productId, oi.CONFIRMED_AT AS confirmedAt, NVL(oi.TOTAL_PRICE, 0) AS itemSalesAmount, CASE WHEN ROW_NUMBER() OVER ( PARTITION BY oi.ORDER_ID ORDER BY oi.ORDER_ITEM_ID ) = 1 AND NOT EXISTS ( SELECT 1 FROM TB_SETTLEMENT_ITEM si2 JOIN TB_ORDER_ITEM oi2 ON oi2.ORDER_ITEM_ID = si2.ORDER_ITEM_ID WHERE oi2.ORDER_ID = oi.ORDER_ID AND NVL(si2.DELIVERY_FEE_AMOUNT, 0) > 0 AND si2.STATUS_CD IN ('INCLUDED', 'HOLD', 'EXCLUDED', 'REFUNDED') ) THEN NVL(o.DELIVERY_FEE, 0) ELSE 0 END AS deliveryFeeAmount, CAST(NULL AS NUMBER) AS returnFeeAmount, CAST(NULL AS VARCHAR2(10)) AS returnFeePayer, NVL(b.FEE_RATE, 5) AS feeRate, 'ORDER_ITEM' AS itemType, o.ORDER_NO AS orderNo, oi.PRODUCT_NAME AS productName FROM TB_ORDER_ITEM oi JOIN TB_ORDER o ON o.ORDER_ID = oi.ORDER_ID JOIN TB_PRODUCT p ON p.PRODUCT_ID = oi.PRODUCT_ID JOIN TB_BUSINESS b ON b.BIZ_NO = NVL(o.BIZ_NO, p.BIZ_NO) WHERE NVL(o.BIZ_NO, p.BIZ_NO) = #{bizNo} AND oi.CONFIRMED_AT IS NOT NULL AND oi.CONFIRMED_AT >= TRUNC(#{periodStart}) AND oi.CONFIRMED_AT < TRUNC(#{periodEnd}) + 1 AND o.ORDER_STATUS <> 'CANCEL' AND NVL(oi.RETURN_STATUS_CD, 'NONE') NOT IN ('REQUESTED', 'RETURNING', 'DONE') AND NOT EXISTS ( SELECT 1 FROM TB_SETTLEMENT_ITEM si WHERE si.ORDER_ITEM_ID = oi.ORDER_ITEM_ID AND si.STATUS_CD IN ('INCLUDED', 'HOLD', 'EXCLUDED', 'REFUNDED') )
AND oi.PRODUCT_ID = #{productId}
) T ORDER BY T.confirmedAt ASC, T.orderItemId ASC

SELECT FEE_RATE
  FROM TB_BUSINESS
 WHERE BIZ_NO = #{bizNo}

SELECT COUNT(*)
  FROM TB_PRODUCT
 WHERE BIZ_NO = #{bizNo}
   AND PRODUCT_ID = #{productId}

SELECT COUNT(*)
  FROM TB_SETTLEMENT_REQUEST
 WHERE BIZ_NO = #{bizNo}
   AND STATUS_CD IN ('REQUESTED', 'APPROVED')
   AND REQUEST_SCOPE = #{requestScope}
   AND TRUNC(TARGET_START) = TRUNC(#{targetStart})
   AND TRUNC(TARGET_END)   = TRUNC(#{targetEnd})


   AND PRODUCT_ID = #{productId}


   AND PRODUCT_ID IS NULL

SELECT BIZ_NAME
  FROM TB_BUSINESS
 WHERE BIZ_NO = #{bizNo}

SELECT COUNT(*)
  FROM TB_SETTLEMENT
 WHERE BIZ_NO = #{bizNo}
   AND BIZ_TYPE = 'STORE'
   AND NVL(REQUEST_TYPE, 'REGULAR') = 'REGULAR'
   AND SETTLE_MONTH = #{settleMonth}
